-- PeaklyTest Jun 2026 · Reading & Writing · Module 1
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('fe8f262e-01e4-58ec-bd50-5da67321306e', 'PeaklyTest Jun 2026 · Reading & Writing · Module 1', 'Reading & Writing', 'Reading & Writing, Module 1 of the Jun 2026 PeaklyTest · 27 questions · 32 minutes', 32, 130, true, 'PeaklyTest Jun 2026 · Reading & Writing', 1)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('3fb5aac6-31cb-58b5-a2e0-19782a2663a1', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text with the most logical and precise word or phrase?', '["complimentary", "straightforward", "infrequent", "hazardous"]'::jsonb, 1, 'In passenger vehicle maintenance guides, brake pad replacement appears to be ______, but as professional technicians will attest, apparent simplicity can mask considerable complexity. Properly done, the procedure requires a detailed inspection of rotors, calipers, and brake lines, as well as detailed checks for fluid leaks and full mechanical operation.'),
  ('ca833eda-02b4-5f5e-8e69-6964c2af2772', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'In the text, what does the word “infrequent” most likely indicate?', '["That long stretches of time presumably intervened between the founding of different farms in the area", "That the farms give the appearance of neglect, with work having been done on them only intermittently", "That the farms that Agee passes by in this area aren’t numerous or located close to one another", "That Agee is frustrated with the progress he is making through the large, wooded area"]'::jsonb, 2, 'The following text is adapted from the 1941 nonfiction book Let Us Now Praise Famous Men, with text by James Agee and photographs by Walker Evans. Agee recounts driving a car through an area of rural Alabama that he is unfamiliar with.

On which road the woods might give way to any extension of farm country there was no deducing: for we were somewhere toward the middle of one of the wider gaps on the road map, and had seen nothing but woods, and <u>infrequent</u> woods farms, for a good while now.'),
  ('b47f591e-4e12-5614-b976-ef42a3690f0c', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text with the most logical and precise word or phrase?', '["indispensable to", "excessive for", "controversial among", "dependent on"]'::jsonb, 3, 'Despite the appearance of many more sophisticated tools in recent years, the ordinary pipe wrench remains ______ plumbers. Its combination of simplicity, durability, and easy adjustability has been impossible for toolmakers to match.'),
  ('89ad51b9-8931-54f8-939e-9e4f2e78e195', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text with the most logical and precise word or phrase?', '["disparity", "trade-off", "interaction", "analogy"]'::jsonb, 4, 'Astronomers analyzing the Sun have discovered an important ______ between magnetically active and quiet regions. In active regions, bursts of ultraviolet light typically precede significant decreases in magnetic energy, whereas in quiet regions, there is a continuous correlation between ultraviolet light intensity and magnetic energy without significant energy drops.'),
  ('a4e52ce9-a77a-5a36-b266-894257f7582e', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice best describes the overall structure of the text?', '["It identifies some scientific instruments and then explains how they are used.", "It describes how stars are born and then explains how they eventually die.", "It explains what constellations are and then gives examples of how some were named.", "It lists the names of some stars and then states how far away they are from Earth."]'::jsonb, 5, 'From Earth, some stars in the night sky appear to form shapes with other stars. These shapes are called constellations. They are often named after the shapes people think the stars form. Some people have thought that one set of stars looks like a hunter. This constellation is named Orion, after a mythical Greek hunter. People have thought that another set of stars looks like a bear. This constellation is named Ursa Major, which means “larger bear” in Latin.'),
  ('976d4aaa-2458-5567-a86e-252d5c5186b6', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice best states the main purpose of the text?', '["To provide an overview of a type of traditional pottery", "To present a history of Korean pottery since the seventeenth century", "To discuss a collection of works by a contemporary artist", "To explain the philosophy that inspired an ancient artistic practice"]'::jsonb, 6, 'The moon jar first gained prominence in Korea in the late seventeenth century. Its shape is distinctive: it is a simple orb created by joining two wheel-spun bowl shapes together. Irregularity is an important feature of a moon jar, so it is traditionally finished with a smooth, milky white glaze that may include bits of debris or dashes of color. Modern ceramists continue to create their own versions of these iconic pieces. Los Angeles artist Raina Lee, for example, uses custom glazes to create thick, cratered surfaces on her moon jars.'),
  ('9b125e92-924c-53df-ad44-9a3253539d36', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It illustrates and expands on one character’s definition of a term that was discussed earlier in the text.", "It contrasts the point of view of one character with that of another through the use of figurative language.", "It presents a position that seems to support the stance of one character and undermine that of another.", "It appears to offer an explanation for the behavior of the character who is the topic of conversation in the text."]'::jsonb, 7, 'The following text is from Richard B. Sheridan’s 1777 satirical play The School for Scandal. Maria, Lady Sneerwell, and Joseph Surface are discussing their mutual acquaintance Sir Benjamin Backbite.

MARIA: [Sir Benjamin] has done nothing—but his conversation is a perpetual libel on all his acquaintance. SURFACE: Aye and the worst of it is there is no advantage in not knowing him, for he’ll abuse a stranger just as soon as his best friend—and [his uncle] is as bad.
SNEERWELL: Nay but we should make allowance. Sir Benjamin is a wit and a poet.
MARIA: For my part—I own madam—wit loses its respect with me, when I see it in the company with malice. What do you think, Mr. Surface?
SURFACE: <u>Certainly, madam, to smile at the jest which plants a thorn on another’s breast is to become a</u> <u>principal in the mischief.</u>'),
  ('5cfd0fdb-909b-590e-9ee4-f8bb75540ef9', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'What is the main topic of the text?', '["How factories train new workers for their jobs", "The future of the pencil industry", "How division of labor increases efficiency", "The invention of the pencil eraser"]'::jsonb, 8, 'Division of labor is a system of dividing the work of making a product among different people who specialize in specific tasks. Instead of each person making an entire product, workers focus on one step in the process. In a pencil factory, for instance, some workers might cut the wood, others insert the graphite, and still others attach the erasers. Workers become skilled at their specific tasks and save time because they’re not switching between different activities. This system has been important for increasing the amount of goods that can be produced in modern economies.'),
  ('c7eac177-c625-569d-90c9-0c951200d349', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice best states the main idea of the text?', '["Attracting pollinators through deception is an effective strategy used by many types of flowering plants.", "Hammer orchids have developed a much better strategy for attracting pollinators than have other flowering plants.", "Hammer orchids have developed the ability to mimic the characteristics of thynnid wasps.", "Unlike species pollinated by hummingbirds, hammer orchids use deception to improve their chances of being pollinated."]'::jsonb, 9, 'Plants that are pollinated by hummingbirds commonly develop brightly colored flowers that attract these highly visual pollinators, increasing the likelihood of successful pollination. Hammer orchids, however, use a different strategy. These orchids facilitate pollination by deceiving their sole pollinator: thynnid wasps. The flower’s structure mimics the appearance of thynnid wasps. When a wasp attempts to interact with what appears to be another wasp, it triggers a hinged part of the flower that flips the insect upside down, positioning it for optimal pollen transfer.'),
  ('f7e6ce67-09cc-5068-b776-8c546fe8feb0', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice best states the main idea of the text?', '["The Mole feels sad that his adventure in the woods is over.", "After being found by his friend, the Mole is embarrassed about getting lost.", "As the landscape gets covered in snow, it no longer seems threatening to the Mole.", "The Mole prefers warm and dry weather to cold and snowy weather."]'::jsonb, 10, 'The following text is adapted from Kenneth Grahame’s 1908 novel The Wind in the Willows. The Mole has been found by a friend after getting lost in the woods. It is beginning to snow.

The Mole saw the wood that had been so dreadful to him in quite a changed aspect. Holes, hollows, pools, pitfalls, and other menaces to the wayfarer were vanishing fast, and a gleaming carpet was springing up everywhere, that looked too delicate to be trodden upon by rough feet.'),
  ('ed38736c-48a5-5ffb-99fe-77a0e8555fd4', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which quotation from Poems of Experience most effectively illustrates the claim?', '["“Is the heart heavy with hope long deferred, / And with prayers that seem vain?” (from “Keep Going”)", "“It is up to you, to be, and do, / What you look for in others. See?” (from “See?”)", "“Over and over the task was set, / Over and over I slighted the work.” (from “The Purpose”)", "“Then gird up your courage, and say ‘I am strong,’ / And keep going.” (from “Keep Going”)"]'::jsonb, 11, 'Poems of Experience is a 1910 collection of poetry by Ella Wheeler Wilcox. In one of her poems, the speaker encourages readers to persevere through difficulty, saying, ______'),
  ('cbddd6cb-6b92-5867-a141-24720915cf85', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice most effectively uses data from the table to complete the example?', '["the populations of both Comoros and Burkina Faso in 2015 with their populations in 2010.", "Mali, which has a high population of 17,600,000 inhabitants and a relatively low density of 14.2 inhabitants/square kilometer, with Comoros, which has a much lower population and a higher density.", "Equatorial Guinea, which has a low density, with Burkina Faso, which has a similar density despite both countries having different geographic sizes.", "the geographic size of Mali (1,240,000 square kilometers) with its relatively high population of 17,600,000 inhabitants."]'::jsonb, 12, '**Population and Population Density of African Countries in 2015**

| Country | Density (inhabitants/km²) | Area (km²) | Estimated population |
| Equatorial Guinea | 30.1 | 28,051 | 845,000 |
| Comoros | 363.1 | 2,170 | 788,000 |
| Mali | 14.2 | 1,240,000 | 17,600,000 |
| Burkina Faso | 66.0 | 274,200 | 18,106,000 |

As the second-most populous continent in the world, Africa was home to an estimated 1.186 billion people in 2015. In a paper for a social studies class, a student nonetheless notes that countries with very large populations may be less densely populated than are countries with much smaller populations, as can be seen by comparing ______'),
  ('0d261f4e-0312-5dae-a8d8-5cc318bb20f6', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which finding, if true, would most directly support the scholars’ claim about Riddle 68?', '["Many of the Exeter Book riddles employ the rhetorical device of prosopopoeia, a form of personification in which a nonhuman entity, usually the solution to a riddle, is represented as speaking, but neither Riddle 68 nor Riddle 69 uses this device.", "Although Riddle 68 opens with a phrase in Old English meaning “I saw” that likewise appears at the beginning of a large number of the Exeter Book riddles, neither it nor Riddle 69 concludes with any phrases that directly invite the audience to solve the riddle, which nearly half of the Exeter Book riddles do.", "Although Riddle 69 appears to be solvable when read on its own or in conjunction with Riddle 68, with “iceberg” or “icicle” having been presented as likely solutions, Riddle 68, whose imagery and sonic patterns are consistent with those of Riddle 69, has been deemed unsolvable given its overly generic clues, unless read in conjunction with Riddle 69.", "Circumstantial evidence, including the fact that most of Riddles 63–72, which appear consecutively in the manuscript, repeat solutions from riddles scattered throughout earlier pages of the manuscript, suggests that Riddles 68 and 69 may have originated from a single source whose author was influenced by those earlier riddles."]'::jsonb, 13, 'The Exeter Book (ca. 960–990 CE) is the sole manuscript source for the entire corpus of Old English riddles. The precise number of riddles is a matter of debate. Identification of consecutive riddles’ boundaries based on content is difficult, given their purposely enigmatic nature, the challenges modern readers face in interpreting the archaic language of Old English, and damage to the manuscript. Moreover, the manuscript lacks any paratextual apparatus—titles, commentary, lists of solutions—to delimit riddles, and the appearance of a distinctive mark to signal the ends of some riddles may be an unreliable clue. For instance, some scholars claim that the use of this mark at the end of the single manuscript line containing the text conventionally known as Riddle 68 may be a scribal error.'),
  ('6125a283-f15e-5ac6-9319-43e33a9e0145', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice most logically completes the text?', '["predicting cloud mergers is more important than predicting cloud splits.", "a single day’s worth of data from one location may not be representative.", "small clouds tend to have little effect on the accuracy of weather forecasts.", "existing forecasting systems already account for shallow cumulus clouds."]'::jsonb, 14, 'Shallow cumulus clouds are too small to be represented accurately in the standard global weather and climate models that weather forecasters use to make predictions. This affects the accuracy of weather forecasts. In 2023, scientists developed a model that predicts how clouds of different sizes interact as they form and change throughout the day. The scientists tested their model using data from a single day in the state of Oklahoma, and it successfully predicted how clouds merged together or split apart over time. Although the results were promising, they are limited in what they can tell us, since ______'),
  ('19dd9c11-9fd7-5b0b-a112-7a0848aca896', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice most logically completes the text?', '["cannot be explained as resulting from the musician’s relatively greater musical expertise.", "indicates that the musician is unlikely to listen to a nonfavorite recording at a higher volume than the nonmusician would.", "does not arise from the musician having a clinically significant reduction in hearing ability as a result of lifetime noise exposure.", "shows that both the musician and the nonmusician have lower hearing ability than would be expected of clinically typical individuals with typical levels of lifetime noise exposure."]'::jsonb, 15, 'Antonia Olivia Dolan and colleagues conducted a study of the differences between musicians and nonmusicians in their preferred volume, in decibels (dB), for listening to various audio recordings including acoustic folk music, classic rock music, and nature sounds. The musicians, who reported much greater lifetime noise exposure than the nonmusicians did, tended to listen to the recordings at higher volumes than the nonmusicians did. The musicians and the nonmusicians had clinically comparable hearing, however, suggesting that while a musician’s preferred volume for playing a favorite recording might be 90.8 dB and a nonmusician’s might be 61.5 dB, this difference ______'),
  ('327116e5-301e-56f1-9a66-0c3e565a31b5', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is facing", "faced", "faces", "will face"]'::jsonb, 16, 'The Billy Possum stuffed toy ______ a skeptical public when it was introduced in 1909 as a potential rival to the popular teddy bear. In fact, one reporter wrote that the toy’s appearance was “likely to give a baby [a] nightmare.”'),
  ('d9d0c5e5-017e-58fa-be18-56bb723d2be0', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["countries residents’,", "country’s residents,", "countries’ resident’s,", "country’s resident’s,"]'::jsonb, 17, 'The Trans Bhutan Trail once served as a vital artery connecting fortresses, monasteries, and markets across the country of Bhutan. After a 60-year hiatus, the historic trail has been restored, a project that employed many of the ______ including homestay owner Sangay Choden, who asserts that the trail’s restoration has helped preserve her village’s culture and tradition.'),
  ('1e4449d5-82e5-5837-b355-f0caf7d65025', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["writing: which was", "writing:", "writing, it was", "writing;"]'::jsonb, 18, 'While being interviewed for the book Latina Authors and Their Muses, poet Maria Gabriela Madrid revealed her favorite book about the craft of ______ Umberto Eco’s Umberto Eco on Literature.'),
  ('1e44d301-f7fb-5044-a1da-40582bc7d27b', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["University; George Starks a professor at Drexel University;", "University, George Starks, a professor at Drexel University;", "University, George Starks a professor at Drexel University,", "University; George Starks, a professor at Drexel University;"]'::jsonb, 19, 'Carnegie Hall’s digital Timeline of African American Music reflects the contributions of many prominent scholars of Black history and music, including Jeff Todd Titon, a professor at Brown ______ and Marisa Parham, a professor at Amherst College.'),
  ('7d2f1fef-e297-5ac2-b9c6-522960adf11d', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["being", "were", "are", "was"]'::jsonb, 20, 'According to historical accounts, medieval recreation—including chess, backgammon, and other board games enjoyed across royal courts and noble households—______ primarily focused on strategic gameplay that mirrored societal structures. Chess, with its hierarchical pieces representing different social classes, was particularly popular during this period.'),
  ('ae6f8c28-a921-54dc-bce6-d352acd7149d', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text with the most logical transition?', '["For instance,", "However,", "There,", "Later,"]'::jsonb, 21, 'Cornelia Konrads is a German sculptor who creates art that seems to be part of its surroundings. Her sculpture entitled red pavilion is built at a pavilion for birdwatching in Taiwan. ______ appearing as a set of red bamboo columns supporting the pavilion, it is cleverly placed into its environment, serving as an example of Konrads’s approach.'),
  ('7cd1e9f4-07fc-5f70-aa16-1938d22f70b5', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text with the most logical transition?', '["For example,", "First,", "Later,", "Previously,"]'::jsonb, 22, 'Early in the morning, when the temperature is still low, the spiny lizard will sit in sunny areas for warmth. ______ as the temperature rises, the spiny lizard will hide in shady spots and under rocks to keep from getting too hot.'),
  ('0a0a40a8-b545-5a78-bcf9-66652bc15f20', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text with the most logical transition?', '["Nevertheless,", "Specifically,", "In addition,", "Earlier,"]'::jsonb, 23, 'A citizen of the Blackfeet Nation, Francis Guardipee was born on his tribe’s reservation in Montana. After studying anthropology at the University of Washington, he returned home, where in 1916 he founded the first all-Native troop of the Boy Scouts. ______ Guardipee was one of the first Native people to become a park ranger at Montana’s Glacier National Park in 1932.'),
  ('7667ba7d-8936-5d0a-9c22-2f572c695c2c', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'Which choice completes the text with the most logical transition?', '["moreover,", "specifically,", "by contrast,", "for instance,"]'::jsonb, 24, 'Under drought conditions, avocado plants produce smaller leaves, a common response to water scarcity that limits transpirational water loss and helps maintain osmotic balance. Sugarcane plants subjected to drought stress, ______ experience a marginal elongation of their leaves, as observed by Misra and colleagues in a recent study.'),
  ('fd937486-f9d0-5e64-a437-c13f985e771e', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'The student wants to emphasize how much bigger the Sun is than Earth. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The actual Earth is far bigger than the model Earth, which is only 3.2 cm in diameter.", "At 1.39 million km in diameter, the Sun is over 100 times bigger than Earth.", "At the Community Solar System Trail in Boston, Massachusetts, the model Sun is 350 cm in diameter.", "The Community Solar System Trail in Boston, Massachusetts, is true to scale."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

In Boston, Massachusetts, there is a true-to-scale model solar system called the Community Solar System Trail.
The scale model Earth is 3.2 cm in diameter.
The scale model Sun is 350 cm in diameter.
The actual Sun is roughly 1.39 million km in diameter.
The actual Earth is roughly 12,742 km in diameter.
The Sun is over 100 times bigger than Earth.'),
  ('ea29dea5-9c7e-5b3a-ace7-b8fdbed7b6bc', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'The student wants to emphasize a similarity between quack grass and giant reed. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Quack grass is an invasive species of wetland plant, and giant reed was first introduced accidentally through seed contamination.", "Quack grass was first introduced accidentally through seed contamination, but it now crowds out crops and native plants.", "Giant reed is an invasive species that crowds out native plants and reduces wildlife habitat, causing environmental harm.", "The harm to ecosystems caused by giant reed and quack grass has led both species to be considered invasive in the US."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

A nonnative species that causes environmental or economic harm when introduced to an ecosystem is considered invasive.
Quack grass is an invasive species of grass that crowds out crops and native plants.
It was first introduced to the US accidentally through seed contamination.
Giant reed is an invasive species of wetland plant that crowds out native plants and reduces wildlife habitat.
It was first introduced to the US to help control erosion.'),
  ('d408468b-a919-5cde-8ea5-6a8f01c92d3f', 'fe8f262e-01e4-58ec-bd50-5da67321306e', 'The student wants to provide a specific example of a type of urban natural area. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["GREEN SURGE studied different types of urban natural areas, which are city spaces that feature natural elements.", "Urban natural areas can benefit cities by increasing plant species diversity.", "One specific example of a type of urban natural area is ruderal areas, which are vacant lots that are overrun with wild vegetation.", "The spaces in European cities that feature natural elements are known as urban natural areas."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

The GREEN SURGE project studied different types of urban natural areas in European cities. Urban natural areas are city spaces that feature natural elements.
Ruderal areas are a type of urban natural area included in the study.
Ruderal areas are defined as vacant lots that are overrun with wild vegetation.
They can benefit cities by increasing plant species diversity.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('3fb5aac6-31cb-58b5-a2e0-19782a2663a1', 1, null, 'Guides make the job look simple ("apparent simplicity"): "straightforward."'),
  ('ca833eda-02b4-5f5e-8e69-6964c2af2772', 2, null, 'Agee saw mostly woods and only a few scattered farms: they were not numerous or close together.'),
  ('b47f591e-4e12-5614-b976-ef42a3690f0c', 0, null, 'Its unmatched simplicity and durability make it essential: "indispensable to" plumbers.'),
  ('89ad51b9-8931-54f8-939e-9e4f2e78e195', 0, null, 'Active and quiet regions behave differently, so the discovery is a "disparity."'),
  ('a4e52ce9-a77a-5a36-b266-894257f7582e', 2, null, 'The text defines constellations, then gives Orion and Ursa Major as examples of how they were named.'),
  ('976d4aaa-2458-5567-a86e-252d5c5186b6', 0, null, 'The text describes the moon jar''s history, shape and glaze, and a modern version: an overview of a type of pottery.'),
  ('9b125e92-924c-53df-ad44-9a3253539d36', 2, null, 'Surface agrees with Maria that laughing at malice is wrong, which undercuts Sneerwell''s excuse for Sir Benjamin.'),
  ('5cfd0fdb-909b-590e-9ee4-f8bb75540ef9', 2, null, 'The text explains division of labor and how specialization saves time and raises output.'),
  ('c7eac177-c625-569d-90c9-0c951200d349', 3, null, 'Unlike hummingbird-pollinated plants, hammer orchids rely on deceiving wasps.'),
  ('f7e6ce67-09cc-5068-b776-8c546fe8feb0', 2, null, 'Snow covers the "menaces" with a gleaming carpet, and the wood no longer looks dreadful to the Mole.'),
  ('ed38736c-48a5-5ffb-99fe-77a0e8555fd4', 3, null, '"Gird up your courage... And keep going" directly encourages persevering.'),
  ('cbddd6cb-6b92-5867-a141-24720915cf85', 1, null, 'Mali has a large population and low density; Comoros has a much smaller population and higher density.'),
  ('0d261f4e-0312-5dae-a8d8-5cc318bb20f6', 2, null, 'If Riddle 68 only makes sense together with Riddle 69, they are likely one riddle and the end mark is an error.'),
  ('6125a283-f15e-5ac6-9319-43e33a9e0145', 1, null, 'The model was tested on one day in one place, so the results may not generalize.'),
  ('19dd9c11-9fd7-5b0b-a112-7a0848aca896', 2, null, 'Their hearing was clinically comparable, so the louder preference is not caused by hearing loss.'),
  ('327116e5-301e-56f1-9a66-0c3e565a31b5', 1, null, 'The event happened in 1909: simple past "faced."'),
  ('d9d0c5e5-017e-58fa-be18-56bb723d2be0', 1, null, 'Singular possessive "country''s" plus plural "residents" (no apostrophe), followed by a comma.'),
  ('1e4449d5-82e5-5837-b355-f0caf7d65025', 1, null, 'A colon introduces the title that names her favorite book.'),
  ('1e44d301-f7fb-5044-a1da-40582bc7d27b', 3, null, 'List items contain commas, so semicolons separate them; the appositive "a professor..." is set off by a comma.'),
  ('7d2f1fef-e297-5ac2-b9c6-522960adf11d', 3, null, 'The subject is singular "recreation": "was."'),
  ('ae6f8c28-a921-54dc-bce6-d352acd7149d', 2, null, 'The sentence describes the sculpture at that location: "There."'),
  ('7cd1e9f4-07fc-5f70-aa16-1938d22f70b5', 2, null, 'Morning warming comes first, then hiding as it gets hotter: "Later."'),
  ('0a0a40a8-b545-5a78-bcf9-66652bc15f20', 2, null, 'This adds another accomplishment of Guardipee: "In addition."'),
  ('7667ba7d-8936-5d0a-9c22-2f572c695c2c', 2, null, 'Sugarcane''s longer leaves contrast with avocado''s smaller leaves: "by contrast."'),
  ('fd937486-f9d0-5e64-a437-c13f985e771e', 1, null, 'It states the Sun''s size and that it is over 100 times bigger than Earth.'),
  ('ea29dea5-9c7e-5b3a-ace7-b8fdbed7b6bc', 3, null, 'Both species harm ecosystems and are considered invasive.'),
  ('d408468b-a919-5cde-8ea5-6a8f01c92d3f', 2, null, 'It names ruderal areas as a specific type and defines them.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Jun 2026 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('f44ed71c-a31c-5c46-a224-036e999fbaa0', 'PeaklyTest Jun 2026 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Jun 2026 PeaklyTest · 27 questions · 32 minutes', 32, 131, true, 'PeaklyTest Jun 2026 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('cff755c0-786d-5599-8dbe-98c7c7412256', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text with the most logical and precise word or phrase?', '["serendipitous", "meticulous", "perfunctory", "resolute"]'::jsonb, 1, 'Both overwatering and underwatering can significantly reduce agricultural yields and waste valuable resources. To avoid these problems, farmers’ management of agricultural irrigation systems must be ______. Following the careful consideration of crop requirements, soil conditions, and weather patterns, farmers need to make precise, minute adjustments to water allocations to ensure the best outcomes.'),
  ('306e78aa-41ce-55e5-9444-2439f2bcaa93', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text with the most logical and precise word or phrase?', '["vulnerabilities", "compensations", "discrepancies", "endorsements"]'::jsonb, 2, 'Lauren Hoult, Michael Smith, and colleagues reviewed 51 studies about positive expressive writing (writing about positive experiences and emotions like happiness) in an attempt to determine what therapeutic outcomes this kind of writing most reliably achieves. However, large ______ across the studies in the methodologies used and health effects assessed prevented a definitive universal conclusion.'),
  ('9a0c86af-a50a-5460-966d-d1e36ac9494d', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text with the most logical and precise word or phrase?', '["peripheral to the practitioner’s discipline", "contingent on the practitioner’s milieu", "indicative of the practitioner’s ingenuity", "controversial within the practitioner’s specialty"]'::jsonb, 3, 'Microhistories tackle “big questions” about broad phenomena via narrow subjects. The questions they ask are often ______. Distinct strains of microhistory emerged at different times in Italy, Iceland, and elsewhere, for example, and while microhistories of the 1980s reflected the era’s interest in labor history, the “global turn” in recent historiography sparked a wave of globally contextualized microhistories.'),
  ('0525261c-92fc-563a-a145-153622428338', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text with the most logical and precise word or phrase?', '["symmetrical", "anachronistic", "discontinuous", "iterative"]'::jsonb, 4, 'Zoochorous trees—those whose seeds are dispersed mainly by animals—are much more prevalent in the Xishuangbanna rainforest plot than in the Harvard Forest, making species distribution in Xishuangbanna considerably more ______. Animal dispersers may congregate at varying distances from parent trees, may carry seeds for varying lengths of time, and may have idiosyncratic spatial trajectories.'),
  ('4b733478-4447-558b-affd-7a3e8da8c487', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice best states the function of the underlined portion in the text as a whole?', '["It implies that the development of television studies as a discipline was slowed by scholars’ early reluctance to accept that television and film have different characteristics.", "It suggests that Newcomb’s observations were the primary catalyst for the emergence of television studies as a formal academic field.", "It introduces an expert opinion that establishes the impetus for a change in scholarly methods of studying television.", "It questions the extent to which the methodologies of film studies informed methodologies in the emerging field of television studies."]'::jsonb, 5, 'Early television analysis in the 1970s and 1980s was shaped by film studies, <u>though media scholar</u> <u>Horace Newcomb notes that tools borrowed from that field often proved inadequate when applied to</u> <u>TV’s distinct characteristics</u>. A recognition of the limitations led researchers to approaches that accounted for a domestic viewing context, embedded advertisements, and serialized narratives, and to a shift in audience research toward ethnographic methods that emphasized viewer engagement. By the 1990s, television studies had emerged as a widely recognized academic field, with scholars founding dedicated journals.'),
  ('58b0894c-e0be-54ca-bc64-33ee4b28b2ec', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice best describes the function of the underlined portion in the text as a whole?', '["It introduces a conceit of the film that helps explain Vertov’s choices as described later in the text.", "It introduces a concept attributed to Vertov, which the remainder of the text affirms is rightly attributed.", "It presents Vertov’s intended message for the film, which the remainder of the text uses as a basis to evaluate how successful the film was at conveying it.", "It presents a metaphor that the text indicates inspired Vertov to structure the film as he did."]'::jsonb, 6, 'Dziga Vertov’s Man with a Movie Camera (1929) not only exhibits striking visual effects like multiple exposure, but it also has as a central idea that <u>the camera itself is a character in the film</u>. The camera’s presence is continually accentuated by showing the operator position it, for example, placing it atop a steel structure, where he then adjusts the camera to capture a view of traffic passing underneath, to which the film cuts immediately after.'),
  ('d8b9eb36-6fcc-5aae-8c49-4e08ba6200f4', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Based on the texts, how would Rose and colleagues (Text 2) most likely respond to the assertion by Slater and Mann (Text 1) about the different prevalence of female birdsong in temperate and tropical areas?', '["They would concede that the geographic difference in prevalence is real but argue that the frequency with which male tropical birds sing has been overstated by previous researchers.", "They would argue that the apparent difference in prevalence may partly reflect a difference in the ease with which female birdsong and male birdsong can be detected.", "They would caution that the seeming difference in prevalence may be an artifact of researchers’ tendency to study birdsong among temperate species more frequently than among tropical species.", "They would raise the possibility that the difference in prevalence may be due to differences in the timing of the mating season among temperate and tropical bird species."]'::jsonb, 7, '**Text 1**

For decades, ornithologists assumed that if they saw a singing Bell’s vireo—a bird species found in temperate North America—they must be observing a male trying to attract a mate or claim territory. As Peter J.B. Slater and Nigel I. Mann have emphasized, however, a similar assumption can’t be made about birds in the tropics, where females sing as often as males do. Slater and Mann call for more research on this discrepancy between tropical and temperate female birdsong.

**Text 2**

Recent evidence shows that a female Bell’s vireo is as capable of song as a male is. In fact, female birdsong is more common among temperate species than currently assumed, claim Evangeline Rose and colleagues. These female songbirds sing less frequently than males do, and in duller tones, making it “easy for researchers to miss the quiet and hidden females and focus on the loud and colorful males,” says Rose.'),
  ('5cf19f0a-e3cf-5079-a2b4-2e99fce8d478', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Based on the texts, what would Salman-Engin and colleagues (Text 1) most likely say about the discussion of the model in Text 2?', '["It underscores that most research on social interactions fails to capture a category of connection that has the capacity to contribute positively to individuals’ sense of well-being.", "It explains researchers’ observations that individuals typically expect interactions with familiar people to be more positive than their interactions with unfamiliar people would be.", "It reflects an overemphasis on relationship longevity in researchers’ evaluations of the relative importance of various connections in an individual’s social network.", "It emphasizes distinctions among types of close connections that aren’t adequately represented in social relations research, since most studies categorize relationships as either close or casual."]'::jsonb, 8, '**Text 1**

Studies contributing to the body of evidence that people generally enjoy socializing have routinely focused on interactions in ongoing relationships (from close confidants to neighbors), but psychologist Selin Salman-Engin and colleagues have demonstrated the benefit of making connections with strangers. Greater positive affect was reported by participants in their study who warmly thanked a shuttle driver than by those who didn’t speak to the driver.

**Text 2**

Social relations research commonly draws on a model that centers an individual within three concentric circles. The innermost circle holds one’s strongest ties (e.g., a treasured friend), the next holds close but less important ties (e.g., a teammate), and the outermost holds weak ties (those more distant but important enough to be counted as part of one’s social network).'),
  ('b3c166f2-6137-59fd-bda2-fee98e5bc680', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'According to the text, which factors seemed to be linked to the behavior of butterflies in Grace Herzel and colleagues’ study?', '["Butterfly color but not weather conditions", "Weather conditions but not butterfly color", "Neither butterfly color nor weather conditions", "Both butterfly color and weather conditions"]'::jsonb, 9, 'Biologist Grace Herzel and colleagues conducted a study of how butterfly color and weather conditions relate to butterfly behavior, which wouldn’t have been possible without data gathered by students and other amateur science enthusiasts in the community. Considering over three years’ worth of data, the researchers found that white butterflies were observed on green flowers more often than any other butterflies were, and that butterflies were observed to feed more often on cloudy days than on other days.'),
  ('614ef9e5-3321-574f-bc19-2352bf431973', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice best describes data from the graph that support the team’s hypothesis?', '["The substitute condition and the control condition both received an average rating of about 4.", "The highest average rating for any of the three conditions was well below the maximum rating of 7.", "The average rating for the control condition was higher than the average rating for the supplement condition.", "The average rating for the substitute condition was higher than the average rating for the supplement condition."]'::jsonb, 10, '![figure](/q/jun26/001.webp)

Having found that emoji images of objects generally have a negative effect when used in social media marketing, Lura Forcum and team studied reactions to three versions of a cafe’s message about coffee: one with a coffee cup emoji after the text (supplement), one with the emoji standing in for the word “coffee” (substitute), and one with no emoji (control). Participants rated their openness to the content of the version of the message they saw, on a scale from 1 (not at all open) to 7 (very open). The team hypothesized that the general effect they’d previously observed would be reduced when an emoji replaces the word it represents.'),
  ('8105c015-63d2-5c7c-9e91-cad50b798ee4', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Based on the text and the table, is the employee’s conclusion supported?', '["No, because the data in the table show that modular construction projects vary considerably in their number of construction days", "Yes, because the Constitutional Hill Coffee Shop was completed in only 23 days", "Yes, because even the project with the longest construction time shown in the table was completed more quickly than it would have been if a different method had been used", "No, because not enough information has been provided to allow a comparison of different construction methods’ efficiency"]'::jsonb, 11, '**Number of Days to Construct Modular Retail Facilities**

| Retail facilities | Construction company | Days to complete construction | Location |
| Constitutional Hill Coffee Shop | Modular Site Solutions | 23 | Johannesburg, South Africa |
| Harrison Street Oasis | UrbanBloc | 106 | California, USA |
| Sundance Ridge Sales Center | WillScot | 136 | Kansas, USA |
| St. Regis Residences–Rye | Cassone Leasing | 443 | New York, USA |

The rapid completion of the Specialty Granules Field Office, a modular structure (a structure built in pieces elsewhere and assembled on site) located in the United States, led an employee at another company to collect data on other facilities built using modular construction methods. The employee concluded that modular construction is more efficient than other construction methods.'),
  ('066db3ea-4add-5719-afeb-d2fa182755fd', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice most effectively uses data from the table to complete the statement?', '["Taiwan, since the percentage of direct-use electricity needed to produce green hydrogen there in 2050 is the lowest of the countries listed.", "the Netherlands, since the percentage of direct-use electricity needed to produce green hydrogen in 2050 is expected to be the same as it was in 2020.", "South Africa, since the estimated electricity needed for green hydrogen production in 2050 is expected to be lower there than in any other country listed.", "Indonesia, since the estimated electricity needed for green hydrogen production in 2050 is expected to be the same as it was in 2020."]'::jsonb, 12, '| Country | Estimated electricity for green hydrogen production (kilowatts per capita), 2020 | Percentage of direct-use electricity capacity, 2020 | Estimated electricity for green hydrogen production (kilowatts per capita), 2050 | Percentage of direct-use electricity capacity, 2050 |
| Indonesia | 0.1 | 51 | 0.1 | 63 |
| Netherlands | 0.6 | 79 | 0.8 | 79 |
| South Africa | 0.0 | 9 | 0.3 | 30 |
| Taiwan | 0.0 | 1 | 0.5 | 17 |

Estimated electricity for green hydrogen production data are rounded to the first decimal place.

In 2020, most hydrogen was produced through steam methane reforming, which emits carbon gases. Using electricity from renewable sources to produce green hydrogen sourced from water would enable countries to reduce industrial carbon emissions, but doing so depends on countries’ capacity for direct-use electricity (electricity produced and used at the same facility). Researchers estimated the amount of electricity needed in 2020 if green hydrogen had been adopted and the amount needed to meet projected green hydrogen demand in 2050. Comparison between these estimates and estimates of capacity suggests that in most countries, projected green hydrogen production would require a larger share of electricity produced on-site. One exception is ______'),
  ('091193ea-7cd6-5d6a-ab40-7a46ac72b6c2', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Based on the text, which choice, if true, best accounts for the observation presented in the underlined sentence?', '["Although less expensive than producing new cells, recycling cells does incur costs, and thus reducing cell lifetimes entails greater cumulative costs.", "Securing new cell materials is more expensive than recycling cell materials, and thus more frequent cell replacement entails greater disparity in cumulative costs.", "Recycled cells lose power conversion efficiency more quickly than new cells do, and thus shorter cell lifetimes reduce the electricity output of plants using recycled cells.", "As the modeled cell lifetime decreases, plant operating costs increase, and thus the LCOE for plants using new cells diverges from that of plants using recycled cells."]'::jsonb, 13, 'Having demonstrated that the power conversion efficiency of new perovskite photovoltaic cells is nearly indistinguishable from that of cells recycled multiple times, Xun Xiao and colleagues evaluated the levelized cost of electricity (LCOE)—a measure of cost per produced electricity unit that incorporates materials acquisition costs as well as operating costs—for power plants utilizing each type of cell. With a modeled 15-year cell lifetime, the LCOE of plants using new cells was 4.99 cents per kilowatt hour, whereas that of plants using cells recycled three times was 4.05 cents per kilowatt hour. <u>Moreover, the</u> <u>LCOE differential grew from 18.8% to 31.3% when the modeled cell lifetime was reduced by two-thirds.</u>'),
  ('642483d2-c99c-5111-a2c8-d22ebdaf6ca2', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice most logically completes the text?', '["starlings’ flocking behavior likely evolved as a response to predation from birds such as peregrine falcons rather than as a response to cold overnight temperatures", "starlings are unlikely to form murmurations in climates where overnight temperatures tend to be warm, regardless of the prevalence of local predators", "starlings’ movements are likely less predictable when a peregrine falcon poses an imminent threat to the flock than when other types of avian predators do", "starlings differ from both smaller birds like larks and larger birds like buzzards in that starlings engage in flocking behaviors primarily when predators are present"]'::jsonb, 14, 'From larks to buzzards, many birds fly in flocks. But starlings uniquely form murmurations, large flocks that swirl in changing shapes before the birds roost together overnight. The two leading explanations for this behavior are the “warmer together” hypothesis, which holds that the goal is to attract more starlings to increase body heat in cold roosts, and the “safer together” hypothesis, which centers on defenses like crowding to make it hard for peregrine falcons and other predators to target a single bird. A study of over 3,000 murmurations across a range of climates found that local temperature was not associated with size, but the presence of a predator correlated with increases in both size and duration. Thus, researchers suggest that ______.'),
  ('e8596b35-e70d-5fde-a835-7a6291485bce', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice most logically completes the text?', '["the gap in the fossil record between 7.0 million years ago and 500,000 years ago could be reflective of poor preservation conditions in the Arabian Peninsula at that time, inadequate fossil recovery efforts, or both.", "even though grasslands likely flourished on the Arabian Peninsula between 7.0 million years ago and 500,000 years ago, the Peninsula was not the only route by which grassland-adapted animals traveled between Africa and Eurasia.", "conditions in the Arabian Peninsula were likely more conducive to fossilization before 7.7 million years ago and after 500,000 years ago than they were in the intervening period.", "the absence of any evidence for African-Eurasian faunal exchange between 7.7 million years ago and 500,000 years ago should not be taken as evidence that the Arabian Peninsula formed a barrier to such exchange."]'::jsonb, 15, 'Animal fossils from the Arabian Peninsula come primarily from two time periods and locations: a late Miocene (7.0–7.7 million years ago) site in the Baynunah Formation and a Pleistocene (12,000–500,000 years ago) site in the Nefud Desert. The 6.5-million-year gap between these fossil assemblages occurs in the context of considerable evidence of concurrent African-Eurasian faunal exchange. While limited exchange may have occurred via island hopping across the 5.3-million-year-old Mediterranean Sea, many of the species that moved between the continents were adapted to grasslands that could not have existed in sufficient size on Mediterranean islands, leaving only the Peninsula as a viable exchange route, a fact suggesting that ______'),
  ('a8c956f8-38ea-5801-86a5-e6c6629111c4', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["have been given", "been given", "being given", "are being given"]'::jsonb, 16, 'According to Roxana Silbert, former artistic director of Hampstead Theatre, the past five decades have seen UK theater companies—once operated as artist cooperatives like the Royal Exchange (with its five founding artistic directors)—evolving toward increasingly corporate structures, with executives rather than creatives ______ decision-making power over programming.'),
  ('45316e1a-4a2b-5430-a02f-76086922d8fe', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the distribution of matter throughout our universe is tracked by researchers using this remarkable instrument that can measure 5,000 galaxies simultaneously.", "researchers track how matter is distributed throughout our universe with this remarkable instrument that can measure 5,000 galaxies simultaneously.", "5,000 galaxies can be measured simultaneously by this remarkable instrument, tracking how matter is distributed throughout our universe.", "this remarkable instrument can measure 5,000 galaxies simultaneously, tracking how matter is distributed throughout our universe."]'::jsonb, 17, 'The scientific team using the Dark Energy Spectroscopic Instrument (DESI) to conduct a cosmological survey, which has generated the largest 3D map of our universe to date, plans to observe roughly 50 million celestial objects. Mounted on a telescope in Arizona, ______'),
  ('f55af027-3efa-5cd3-bad4-62d23a883e8d', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["populations and", "populations,", "populations", "populations:"]'::jsonb, 18, 'Noise from human activity poses significant challenges to animal ______ ambient noise from automobile traffic, for example, may mask environmental signals that animals depend on for their survival.'),
  ('11e131bb-4dcc-51f8-9ee9-af9e85786277', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["floor,", "floor:", "floor and", "floor"]'::jsonb, 19, 'While calling the frogfish (family Antennariidae) a “walking fish” might suggest a creature that has fully transitioned to terrestrial life, the frogfish’s unique locomotion represents a specialized adaptation for movement along the ocean ______ the frogfish’s modified pectoral fins function similarly to legs, allowing this unusual marine predator to “walk” across the seafloor in the tropical and subtropical waters it inhabits.'),
  ('19300ff3-21c7-5880-a31d-e9394145ca04', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["highlights", "has highlighted", "highlighting", "is highlighting"]'::jsonb, 20, 'In recent years, the English writer Mary Robinson (1758–1800), whose poetry was widely read during her lifetime, has been rediscovered by contemporary audiences—a resurgence of interest that is largely due to literary scholars such as Anne Janowitz, whose work ______ the richness of Robinson’s poems and the poet’s historical importance to the Romantic literary movement encourages a broader rethinking of British Romanticism itself.'),
  ('8c8f9c47-712f-562b-8a54-23c3ab35db3d', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["have become", "becoming", "becomes", "become"]'::jsonb, 21, 'In Danger Mouse’s Grey Album, each of the instrumental samples—isolated from the Beatles’ White Album and then reconstructed into entirely new arrangements—______ raw material used in the instrumental collage that backs unaltered vocal tracks from Jay-Z’s Black Album, resulting in a remarkable integration of two disparate musical genres.'),
  ('4c63a683-e4c1-54c7-a874-2315c87df28c', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text with the most logical transition?', '["In addition,", "Nevertheless,", "There,", "However,"]'::jsonb, 22, 'Forrest Myers’s steel sculpture Four Corners is displayed at Storm King Art Center, an outdoor sculpture park in New York. ______ it endures rain, snow, heat, and humidity. Myers’s sculpture is particularly well suited to withstand these elements, though, because it is made of corrosion-resistant steel.'),
  ('73dbe81a-6f7c-5053-8d2b-33bf8ba6afd7', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text with the most logical transition?', '["Nevertheless,", "In addition,", "To that end,", "In other words,"]'::jsonb, 23, 'Shards of ceramic husking trays have been recovered across northwestern Mesopotamia, dating back to the Late Neolithic Period. Taranto et al. wanted to determine whether the use-wear patterns on the husking tray shards were consistent with the baking of lipid-infused doughs. ______ they baked such doughs in replicas of the husking trays and compared the use-wear patterns on the replicas with those on the shards.'),
  ('b14b2e8b-5a32-549b-9187-df47b0955f6c', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text with the most logical transition?', '["Paradoxically,", "By extension,", "Essentially,", "Predictably,"]'::jsonb, 24, 'Quantum entanglement, in which two particles seem to influence each other instantly even when separated by vast distances, appears to contradict classical physics, which holds that nothing can travel faster than light and that causality is unidirectional—causes precede effects. ______ physicist Emily Adlam has argued that retrocausality—though also seemingly at odds with classical ideas—may help account for quantum entanglement without violating classical physics by allowing future and past states to be correlated within a fixed space-time.'),
  ('369a0045-6451-5ac2-a5c9-26209ccaf334', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text with the most logical transition?', '["That is,", "In addition,", "Granted,", "Therefore,"]'::jsonb, 25, 'In a 2003 study, Hall and Fransson identified a distinct time-pressure effect on avian molting behaviors in lesser whitethroats, with potential implications for migration fitness. ______ the researchers observed that birds exposed to shifted daylight patterns suggesting a more imminent departure molted quicker and grew shorter wing feathers than did the controls, likely resulting in decreased migration speeds.'),
  ('b7c35877-7511-569e-a067-dfa220c3ac26', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'Which choice completes the text with the most logical transition?', '["Similarly,", "However,", "Indeed,", "For example,"]'::jsonb, 26, 'While phenomenology and liberal political philosophy are both associated with philosophy’s contemporary period (early 1900s to the present day), these two schools of thought propose distinctly different answers to questions about the nature of knowledge, reality, and the human condition. ______ the term “contemporary period” describes a period of wide-ranging philosophical discourse rather than an era of homogeneity and agreement.'),
  ('96ee15ca-2509-592c-bf0f-ba305ef03ceb', 'f44ed71c-a31c-5c46-a224-036e999fbaa0', 'The student wants to cite a historian to explain why Digby wrote De Arte Natandi. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["In De Arte Natandi, Digby wrote that he “hoped to… elevate [swimming] from a crude, mechanical function of the hands and feet” by “providing instructions for… aquatic ‘refinements.’”", "According to Valosik, Digby wrote De Arte Natandi to describe and illustrate “once revered” aquatic stunts from ancient Rome, such as “ringing the bells” and “the leap of the goat.”", "Valosik claims that, by writing De Arte Natandi, “Digby hoped to revive swimming… and elevate it from a crude, mechanical function… to an artful science.”", "As Valosik claims, with De Arte Natandi, Digby developed the first modern swimming manual in order to illustrate why “a once revered skill… had all but died out during Europe’s Dark Ages.”"]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Swimming was celebrated in ancient Rome but fell out of favor throughout Europe’s Dark Ages. English theologian Everard Digby wrote the first modern swimming manual, De Arte Natandi, in 1587. Digby’s manual described and illustrated a variety of aquatic stunts that he had developed (e.g., “ringing the bells,” “the leap of the goat”).
Historian Vicki Valosik claims, “In providing instructions for these aquatic ‘refinements,’ Digby hoped to revive swimming—a once revered skill that had all but died out during Europe’s Dark Ages—and elevate it from a crude, mechanical function of the hands and feet to an artful science.”')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('cff755c0-786d-5599-8dbe-98c7c7412256', 1, null, 'Farmers must make careful, precise adjustments: "meticulous."'),
  ('306e78aa-41ce-55e5-9444-2439f2bcaa93', 2, null, 'Studies differed widely in methods and effects measured: "discrepancies."'),
  ('9a0c86af-a50a-5460-966d-d1e36ac9494d', 1, null, 'The questions change with time and place (Italy vs Iceland, 1980s vs the global turn): they depend on the historian''s milieu.'),
  ('0525261c-92fc-563a-a145-153622428338', 2, null, 'Animals drop seeds at irregular distances and paths, so distribution is patchy: "discontinuous."'),
  ('4b733478-4447-558b-affd-7a3e8da8c487', 2, null, 'Newcomb''s point that film tools were inadequate explains why scholars changed their methods.'),
  ('58b0894c-e0be-54ca-bc64-33ee4b28b2ec', 0, null, 'The idea that the camera is a character explains the later description of how the film keeps showing the camera.'),
  ('d8b9eb36-6fcc-5aae-8c49-4e08ba6200f4', 1, null, 'Rose says quiet, dull-toned females are easy to miss, so the apparent difference may come from detectability.'),
  ('5cf19f0a-e3cf-5079-a2b4-2e99fce8d478', 0, null, 'The model covers only ongoing ties, not strangers, the category Salman-Engin showed can raise well-being.'),
  ('b3c166f2-6137-59fd-bda2-fee98e5bc680', 3, null, 'Color (white butterflies on green flowers) and weather (cloudy days) were both linked to behavior.'),
  ('614ef9e5-3321-574f-bc19-2352bf431973', 3, null, 'The hypothesis is that substituting reduces the negative effect: the substitute rating (about 4.1) beats the supplement rating (about 3.7).'),
  ('8105c015-63d2-5c7c-9e91-cad50b798ee4', 3, null, 'The table shows only modular projects, so there is nothing to compare with other construction methods.'),
  ('066db3ea-4add-5719-afeb-d2fa182755fd', 1, null, 'The Netherlands needs 79% in both 2020 and 2050, so its share does not grow.'),
  ('091193ea-7cd6-5d6a-ab40-7a46ac72b6c2', 1, null, 'Shorter lifetimes mean more replacements; if new materials cost more than recycled ones, the cost gap widens.'),
  ('642483d2-c99c-5111-a2c8-d22ebdaf6ca2', 0, null, 'Size tracked predators, not temperature, which supports "safer together" over "warmer together."'),
  ('e8596b35-e70d-5fde-a835-7a6291485bce', 3, null, 'Exchange must have used the Peninsula, so the missing fossils do not mean animals could not cross it.'),
  ('a8c956f8-38ea-5801-86a5-e6c6629111c4', 2, null, '"with executives... being given" is a with-phrase that needs a participle.'),
  ('45316e1a-4a2b-5430-a02f-76086922d8fe', 3, null, 'The modifier "Mounted on a telescope" must describe the instrument.'),
  ('f55af027-3efa-5cd3-bad4-62d23a883e8d', 3, null, 'A colon introduces the example that explains the challenges.'),
  ('11e131bb-4dcc-51f8-9ee9-af9e85786277', 1, null, 'A colon introduces the explanation of how the frogfish "walks."'),
  ('19300ff3-21c7-5880-a31d-e9394145ca04', 2, null, '"whose work highlighting..." is the subject; "encourages" is the verb, so a participle is needed.'),
  ('8c8f9c47-712f-562b-8a54-23c3ab35db3d', 2, null, 'The subject is "each": "becomes."'),
  ('4c63a683-e4c1-54c7-a874-2315c87df28c', 2, null, 'Outdoors at the park, the sculpture endures weather: "There."'),
  ('73dbe81a-6f7c-5053-8d2b-33bf8ba6afd7', 2, null, 'Baking doughs in replicas was the method chosen to reach that goal: "To that end."'),
  ('b14b2e8b-5a32-549b-9187-df47b0955f6c', 0, null, 'An idea that is itself at odds with classical physics is used to avoid violating it: "Paradoxically."'),
  ('369a0045-6451-5ac2-a5c9-26209ccaf334', 0, null, 'The sentence restates the time-pressure effect in concrete terms: "That is."'),
  ('b7c35877-7511-569e-a067-dfa220c3ac26', 2, null, 'The sentence confirms the point about deep disagreement: "Indeed."'),
  ('96ee15ca-2509-592c-bf0f-ba305ef03ceb', 2, null, 'It cites Valosik and gives Digby''s purpose: to revive swimming and make it an artful science.')
