insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('26573267-93fc-50a5-91ae-add3367b91da', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'The table summarizes members of a local organization by age and whether they live north or south of Center St. If a member of the organization is selected at random, what is the probability that the selected member is at least 45 years old?', '["$\\frac{33}{135}$", "$\\frac{35}{135}$", "$\\frac{100}{135}$", "$\\frac{102}{135}$"]'::jsonb, 1, '|  | Live north of Center St. | Live south of Center St. | Total |
| Less than 45 years old | 21 | 12 | 33 |
| At least 45 years old | 14 | 88 | 102 |
| Total | 35 | 100 | 135 |'),
  ('988c68f0-7be8-5cbf-a312-fa81eb236bda', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'In triangle $XY Z$, the measure of angle $X$ is $55°$ and the measure of angle $Y$ is $81°$. What is the measure of angle $Z$?', '["$26°$", "$44°$", "$136°$", "$226°$"]'::jsonb, 2, null),
  ('ee276b23-9871-5989-885e-486b7be60a77', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'A chemist combines water and isopropanol to make a mixture with a volume of $31$ milliliters (mL). The volume of isopropanol in the mixture is $10$ mL. What is the volume of water, in mL, in the mixture? (Assume that the volume of the mixture is the sum of the volumes of water and isopropanol before they were mixed.)', '[]'::jsonb, 3, null),
  ('85234ba9-b632-5cf6-962a-2b0e06929254', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'A pet service that takes care of both cats and dogs can care for at most $31$ animals. Which inequality represents this situation, where $c$ is the number of cats and $d$ is the number of dogs?', '["$c + d \\le 31$", "$c + d \\ge 31$", "$c - d \\le 31$", "$c - d \\ge 31$"]'::jsonb, 4, null),
  ('0e46d49b-f8dc-505e-a462-2bb89b65f733', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'Line $c$ is defined by $y = 2x + 9$. Line $d$ is parallel to line $c$ in the $xy$-plane. What is the slope of line $d$?', '["$2$", "$7$", "$9$", "$11$"]'::jsonb, 5, null),
  ('fb72580f-a3ae-5069-a939-b1968325ab3b', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'If $5x - 9 = 6$, what is the value of $5x + 9$?', '["$-3$", "$3$", "$12$", "$24$"]'::jsonb, 6, null),
  ('cd063ceb-0d69-5d0d-8983-b91494f855aa', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'The ratio of the side length of square A to the side length of square B is $4$ to $20$. Square A has a side length of $26$ inches. What is the side length, in inches, of square B?', '[]'::jsonb, 7, null),
  ('02b8155a-7728-5c1b-a56a-e70272f737e9', 'fd34ce2f-667e-52d1-9470-61236121dbaf', '$p(x) = 131 - 7x$
The function $p$ shown gives the number of blank sheets of paper, $p(x)$, remaining in a printer $x$ days after the printer had been loaded with paper. Which statement is the best interpretation of $p(3) =$ $110$?', '["There were $3$ blank sheets of paper remaining in the printer $110$ days after the printer had been loaded with paper.", "The number of blank sheets of paper remaining in the printer decreased by a total of $3$ sheets after $110$ days.", "There were $110$ blank sheets of paper remaining in the printer $3$ days after the printer had been loaded with paper.", "The number of blank sheets of paper remaining in the printer decreased by a total of $110$ sheets after $3$ days."]'::jsonb, 8, null),
  ('ec0a4d99-2fe8-5623-a4d7-7dd9d8ae6b9e', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'During a physics experiment, the speed of an object was determined to be $172.0$ inches per second. What is this speed in feet per second? ($12$ inches $= 1$ foot)', '[]'::jsonb, 9, null),
  ('41fa6447-3522-55e2-8457-a527d6c9cb3a', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'Which of the following equations is the most appropriate linear model for the data shown?', '["$y = -2x$", "$y = -x$", "$y = x$", "$y = 2x$"]'::jsonb, 10, 'The scatterplot shows the relationship between two variables, $x$ and $y$.

![figure](/q/jun26/002.webp)'),
  ('b9eecd7d-03a9-59c4-8a63-3306d0bbb87a', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'The measure of angle $Z$ is $240°$. What is the measure, in radians, of angle $Z$?', '["$\\frac{2π}{3}$", "$\\frac{4π}{3}$", "$\\frac{8π}{3}$", "$4π$"]'::jsonb, 11, null),
  ('f98bb530-db35-58a3-8477-3e2c1ba5f3d1', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'Triangle $FGH$ is similar to triangle $JKL$, where angle $F$ corresponds to angle $J$ and angles $G$ and $K$ are right angles. If $\sin (F) = \frac{144}{145}$, what is the value of $\sin (J)$?', '["$\\frac{17}{145}$", "$\\frac{144}{145}$", "$\\frac{145}{144}$", "$\\frac{145}{17}$"]'::jsonb, 12, null),
  ('ee13ec78-e0a1-567a-92fb-eaf6923a3ea0', 'fd34ce2f-667e-52d1-9470-61236121dbaf', '$x^{2} - 7x + 12 = 0$
How many distinct real solutions does the given equation have?', '["Exactly one", "Exactly two", "Infinitely many", "Zero"]'::jsonb, 13, null),
  ('d6ebb8c1-18d3-5310-88da-e18408337317', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'The estimated fuel cost $C(x)$, in dollars, to drive a vehicle $100$ kilometers is given by the function $C(x) = 0.0019x^{2} - 0.248x + 12.62$, where $x$ is the average speed, in kilometers per hour, of the vehicle. If the function $C$ is graphed in the $xy$-plane, where $y = C(x)$, what is the best interpretation of the point $(60,4.58)$ on the graph?', '["The estimated fuel cost to drive the vehicle at an average speed of $4.58$ kilometers per hour increases by \\$60 each hour.", "The estimated fuel cost to drive the vehicle at an average speed of $60$ kilometers per hour increases by \\$4.58 each hour.", "The estimated fuel cost to drive the vehicle $100$ kilometers at an average speed of $4.58$ kilometers per hour is \\$60.", "The estimated fuel cost to drive the vehicle $100$ kilometers at an average speed of $60$ kilometers per hour is \\$4.58."]'::jsonb, 14, null),
  ('c029bd9d-5885-5c1a-9640-8890c1618334', 'fd34ce2f-667e-52d1-9470-61236121dbaf', '$\frac{1}{x - 1} = \frac{x - 7}{-x - 1.25}$
What is one of the solutions to the given equation?', '[]'::jsonb, 15, null),
  ('3d6c9641-4bcf-5ad6-aa98-7fe9db800813', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'The length of a rectangle’s diagonal is $\sqrt{34}$, and the length of one of the rectangle’s sides is $5$. What is the perimeter of the rectangle?', '["$34$", "$16$", "$15$", "$8$"]'::jsonb, 16, null),
  ('3acd4156-9df4-5161-b46a-817828f89791', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'The table shows three values of $x$ and their corresponding values of $y$, where $n$ is a constant, for the linear relationship between $x$ and $y$. What is the slope of the line that represents this relationship in the $xy$-plane?', '["$-\\frac{64}{5}$", "$-\\frac{5}{64}$", "$\\frac{n+64}{-5}$", "$\\frac{2n-64}{5}$"]'::jsonb, 17, '| $x$ | $y$ |
| $-10$ | $n + 128$ |
| $-5$ | $n + 64$ |
| $0$ | $n$ |'),
  ('da481ddd-585b-5755-ae02-037711c7ae22', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'During a trip, a car traveled a total of $510$ miles on city roads and highways and used a total of $17$ gallons of gas. The car traveled an average of $29$ miles per gallon of gas on city roads and $35$ miles per gallon of gas on highways. Which system of equations represents this situation, where $c$ is the number of miles the car traveled on city roads and $h$ is the number of miles the car traveled on highways?', '["$c + h = 17$\n\n$\\frac{c}{29} + \\frac{h}{35} = 510$", "$c + h = 17$\n\n$29c + 35h = 510$", "$c + h = 510$\n\n$\\frac{c}{29} + \\frac{h}{35} = 17$", "$c + h = 510$\n\n$29c + 35h = 17$"]'::jsonb, 18, null),
  ('2940cc35-dd20-53a5-8ca1-0802cf8b99b3', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'The exponential function $g$ is defined by $g(x) = ab^{x}$, where $a$ and $b$ are positive constants. If $g(c) = m$ and the value of $g(c + 1)$ is $82%$ more than the value of $m$, where $c$ and $m$ are constants, what is the value of $b$?', '["$0.18$", "$0.82$", "$1.82$", "$3.64$"]'::jsonb, 19, null),
  ('67d29694-aec8-57a7-acae-3afc17a9b4fd', 'fd34ce2f-667e-52d1-9470-61236121dbaf', '$f(x) = (x - a)(x - b)$
The function $f$ is defined by the given equation, where $a$ and $b$ are integer constants. If $f(11) > 0$, $f(14) < 0$, and $f(17) > 0$, what is one possible value of $a + b$?', '[]'::jsonb, 20, null),
  ('30eed30f-b28f-5bee-9f19-6d6d1d09743b', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'A machine makes 2-inch, 7-inch, and 11-inch parts. During a certain day, the number of 2-inch parts that the machine makes is $5$ times the number $n$ of 7-inch parts, and the number of 11-inch parts is $4$. During this day, the machine makes $100$ parts total. Which equation represents this situation?', '["$2(5n) + 7n + 11(4) = 100$", "$2n + 7n + 11n = 100$", "$5n + 4 = 100$", "$6n + 4 = 100$"]'::jsonb, 21, null),
  ('d65cf872-0ca0-5477-a26f-8b096c7ac8fe', 'fd34ce2f-667e-52d1-9470-61236121dbaf', 'In a certain colony, one of the bees is a queen bee. Of the bees in this colony that are not the queen bee, $85%$ are worker bees, and the remaining bees are drones. If there are $11,109$ drones in this colony, what is the total number of worker bees in this colony?', '[]'::jsonb, 22, null)
