insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('26573267-93fc-50a5-91ae-add3367b91da', 3, null, '102 of the 135 members are at least 45 years old: $\frac{102}{135}$.'),
  ('988c68f0-7be8-5cbf-a312-fa81eb236bda', 1, null, '$180 - 55 - 81 = 44$ degrees.'),
  ('ee276b23-9871-5989-885e-486b7be60a77', null, array['21']::text[], '$31 - 10 = 21$ mL of water.'),
  ('85234ba9-b632-5cf6-962a-2b0e06929254', 0, null, 'At most 31 animals in total: $c + d \le 31$.'),
  ('0e46d49b-f8dc-505e-a462-2bb89b65f733', 0, null, 'Parallel lines have equal slopes: $2$.'),
  ('fb72580f-a3ae-5069-a939-b1968325ab3b', 3, null, '$5x = 15$, so $5x + 9 = 24$.'),
  ('cd063ceb-0d69-5d0d-8983-b91494f855aa', null, array['130']::text[], 'Square B is $\frac{20}{4} = 5$ times as long: $5(26) = 130$ inches.'),
  ('02b8155a-7728-5c1b-a56a-e70272f737e9', 2, null, '$p(3) = 110$: 110 sheets remain 3 days after loading.'),
  ('ec0a4d99-2fe8-5623-a4d7-7dd9d8ae6b9e', null, array['43/3', '14.33', '14.333']::text[], '$172.0 \div 12 = 14.33...$ feet per second.'),
  ('41fa6447-3522-55e2-8457-a527d6c9cb3a', 2, null, 'The points rise about 1 unit in $y$ per unit in $x$, starting near the origin: $y = x$.'),
  ('b9eecd7d-03a9-59c4-8a63-3306d0bbb87a', 1, null, '$240 \cdot \frac{π}{180} = \frac{4π}{3}$.'),
  ('f98bb530-db35-58a3-8477-3e2c1ba5f3d1', 1, null, 'Corresponding angles of similar triangles are equal, so $\sin J = \sin F = \frac{144}{145}$.'),
  ('ee13ec78-e0a1-567a-92fb-eaf6923a3ea0', 1, null, '$(x - 3)(x - 4) = 0$ has two distinct solutions.'),
  ('d6ebb8c1-18d3-5310-88da-e18408337317', 3, null, '$x$ is the speed and $C(x)$ the cost for 100 km: at 60 km/h the cost is \$4.58.'),
  ('c029bd9d-5885-5c1a-9640-8890c1618334', null, array['5.5', '1.5', '11/2', '3/2']::text[], 'Cross-multiplying gives $-x - 1.25 = (x - 7)(x - 1)$, so $x^{2} - 7x + 8.25 = 0$ and $x = 1.5$ or $x = 5.5$.'),
  ('3d6c9641-4bcf-5ad6-aa98-7fe9db800813', 1, null, 'The other side is $\sqrt{34 - 25} = 3$, so the perimeter is $2(5 + 3) = 16$.'),
  ('3acd4156-9df4-5161-b46a-817828f89791', 0, null, 'From $x = -5$ to $x = 0$, $y$ falls by $64$: slope $\frac{-64}{5}$.'),
  ('da481ddd-585b-5755-ae02-037711c7ae22', 2, null, 'Total miles $c + h = 510$; gallons used $\frac{c}{29} + \frac{h}{35} = 17$.'),
  ('2940cc35-dd20-53a5-8ca1-0802cf8b99b3', 2, null, '$g(c + 1) = b \cdot g(c) = 1.82m$, so $b = 1.82$.'),
  ('67d29694-aec8-57a7-acae-3afc17a9b4fd', null, array['27', '28', '29']::text[], '$f$ is negative between its zeros, so one zero is 12 or 13 and the other is 15 or 16: $a + b$ is 27, 28 or 29.'),
  ('30eed30f-b28f-5bee-9f19-6d6d1d09743b', 0, null, 'Lengths times counts: $2(5n) + 7n + 11(4) = 100$.'),
  ('d65cf872-0ca0-5477-a26f-8b096c7ac8fe', null, array['62951']::text[], 'Drones are 15% of non-queen bees: $\frac{11,109}{0.15} = 74,060$. Workers are $74,060 - 11,109 = 62,951$.')
