insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('65344318-6149-5801-bdad-dfc5dc446af2', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'In the $xy$-plane, the graph of the equation $(x - 2)^{2} + (y - 10)^{2} = 4$ is a circle. The point $(4,c)$, where $c$ is a constant, lies on this circle. What is the value of $c$?', '[]'::jsonb, 1, null),
  ('4cbe3e08-7782-5ddf-99e0-d51965db76e1', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', '$v = -\frac{w}{119x}$
The given equation relates the distinct numbers $v$, $w$, and $x$. Which equation correctly expresses $w$ in terms of $v$ and $x$?', '["$w = -119vx$", "$w = -\\frac{119v}{x}$", "$w = -\\frac{x}{119v}$", "$w = v + 119x$"]'::jsonb, 2, null),
  ('b34247d7-c749-5e54-a56f-ba51603bfaed', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', '$3(x + \frac{b}{3} - 16) = 3x$
In the given equation, $b$ is a constant. The equation has infinitely many solutions. What is the value of $b$?', '[]'::jsonb, 3, null),
  ('18ababd7-a0a2-516b-804e-4c980187e449', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'What is an equation of the graph shown, where $y = f(x)$?', '["$f(x) = x^{2} - 4$", "$f(x) = x^{2} + 3x - 4$", "$f(x) = x^{2} - 3x - 4$", "$f(x) = 2x^{2} - 3x - 4$"]'::jsonb, 4, '![figure](/q/jun26/003.webp)'),
  ('66c19bbd-69db-5d6a-99bc-72608170da6f', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'In the relationship between $x$ and $y$, each increase of $1$ in the value of $x$ decreases the value of $y$ by $\frac{7}{2}$. When $x = -2$, $y = 5$. Which equation represents this relationship?', '["$y = -\\frac{7}{2}x - 2$", "$y = -\\frac{7}{2}x + 2$", "$y = \\frac{7}{2}x - 2$", "$y = \\frac{7}{2}x + 2$"]'::jsonb, 5, null),
  ('1e3c5f3f-20d5-5a24-9811-bb090b39dbc6', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'The function $f$ is defined by $f(x) = (x - 3) + 2$. If $f(a) = 7$, what is the value of $a + 3$?', '["$5$", "$10$", "$11$", "$21$"]'::jsonb, 6, null),
  ('f0c80805-5669-5771-b564-c2c4a9568255', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', '$40(0.6r - 0.8s) = -4,320$
$70(0.8r + 0.6s) = 7,420$
The solution to the given system of equations is $(r,s)$. What is the value of $r + s$?', '[]'::jsonb, 7, null),
  ('2683886f-eada-5bc8-b75a-de807c017081', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', '$f(x) = 9((\frac{1}{8})^{x} + 7)$
The function $f$ is defined by the given equation. For all values of $x$, the value of $f(x)$ is greater than $k$, where $k$ is a constant. What is the greatest possible value of $k$?', '["$0$", "$7$", "$63$", "$504$"]'::jsonb, 8, null),
  ('7bb3620c-1259-5d4c-9a55-3800f0197d62', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'The line models the possible combinations of the number of boxes of cups, $x$, and the number of boxes of mugs, $y$, a company can purchase for a total price of \$880. What is the price, in dollars, per box of cups?', '["$10$", "$20$", "$44$", "$88$"]'::jsonb, 9, '![figure](/q/jun26/004.webp)'),
  ('2cedacf8-643c-5756-a44f-9fd40daee55a', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', '$12x + 11y = c$
$11x - 12y = c$
In the given system of equations, $c$ is a positive constant. Which of the following could be the point where the graphs of the equations in this system intersect in the $xy$-plane?', '["$(c,0)$", "$(c, \\frac{c}{23})$", "$(10,230)$", "$(10,-\\frac{10}{23})$"]'::jsonb, 10, null),
  ('4d26b06a-b642-5231-81ee-db6bfca5e8f6', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', '$y > 2x + k$
$y < 9 - x$
In the given system of inequalities, $k$ is a positive constant. Which of the following represents the $x$- coordinates of all the points $(x,y)$ that satisfy this system in the $xy$-plane?', '["$x > \\frac{k}{9}$", "$x < \\frac{k}{9}$", "$x > \\frac{9-k}{3}$", "$x < \\frac{9-k}{3}$"]'::jsonb, 11, null),
  ('12b96dda-2760-575b-9d43-6b8792998469', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'An online store is offering two different discounts on its sweaters: a bulk discount for large orders and a coupon discount. For orders of $n$ sweaters, where $10 < n < 50$, a bulk discount of $n%$ off the original price of \$44 is applied to the price of each sweater. If a coupon is applied to the order, a discount of an additional \$3 is applied to the price of each sweater, after the bulk discount is applied. For a certain order with both the bulk discount and the coupon discount applied, the total price after the discounts for the sweaters purchased was \$834. How many sweaters were purchased in this order?', '["$19$", "$20$", "$30$", "$42$"]'::jsonb, 12, null),
  ('530b42d6-34cd-5ef4-857d-a58251e25115', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'An entomologist is studying the growth rate of various insect species in a controlled environment. For one particular species being studied in the controlled environment, an exponential model predicts that a population with an initial measurement of $8$ organisms will increase by $160%$ every $24$ days. Which equation represents this model, where $y$ is the predicted number of organisms in the population $x$ days since the initial measurement?', '["$y = 8(1.60)^{24x}$", "$y = 8(2.60)^{24x}$", "$y = 8(1.60)^{\\frac{x}{24}}$", "$y = 8(2.60)^{\\frac{x}{24}}$"]'::jsonb, 13, null),
  ('6015a7c7-9cf9-5ccb-b7d5-2b8b153142c7', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'In the figure, line $LQ$ intersects line $MP$ at point $R$, and line $LM$ is parallel to line $PQ$. The lengths of $MR$, $LR$, and $RP$ are $9$, $10$, and $13$, respectively. What is the length of $LQ$?', '["$\\frac{130}{9}$", "$\\frac{220}{13}$", "$\\frac{211}{9}$", "$\\frac{220}{9}$"]'::jsonb, 14, '![figure](/q/jun26/005.webp)'),
  ('82dc9bc3-9a1e-51c8-8ab9-6e21dac624ad', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'Data set B is created by multiplying the $y$-value of each data point from data set A by $30$. Which of the following equations is the most appropriate model for data set B?', '["$y = 5(2.03)^{x}$", "$y = 151(2.03)^{x}$", "$y = 5(2.03)^{x} + 30$", "$y = 30(2.03)^{x} + 30$"]'::jsonb, 15, 'The scatterplot shows data set A.

![figure](/q/jun26/006.webp)'),
  ('cc3836fe-881e-55c6-bd9c-eea0b4490bb6', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'The data value $16$ was recorded in error and is removed from data set A to create data set B, which consists of the remaining $40$ data values. Which statement best compares the median of data set A and the median of data set B?', '["The median of data set B is less than the median of data set A.", "The median of data set B is equal to the median of data set A.", "The median of data set B is greater than the median of data set A.", "There is not enough information to compare the medians of the two data sets."]'::jsonb, 16, '| Value | Frequency |
| 0 | 1 |
| 1 | 7 |
| 2 | 8 |
| 3 | 9 |
| 4 | 8 |
| 5 | 7 |
| 16 | 1 |'),
  ('0abf8ec2-af4d-5cc8-8b4e-0263e518940c', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', '$51x^{2} + (51b + a)x + ab = 0$
In the given equation, $a$ and $b$ are positive constants. The product of the solutions to the given equation is $kab$, where $k$ is a constant. What is the value of $k$?', '["$51$", "$1$", "$\\frac{1}{3}$", "$\\frac{1}{51}$"]'::jsonb, 17, null),
  ('0e2ca8a2-bd80-5999-9468-1509a50f05d9', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'A right square pyramid has a surface area of $16 + 8\sqrt{293}$ square inches, which includes a base area of $16$ square inches. What is the height, in inches, of this pyramid?', '[]'::jsonb, 18, null),
  ('303ef118-abd6-520e-a27c-fc27dad6368a', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'The mass of object A is $492%$ of the mass of object B, and the mass of object A is $0.820%$ of the mass of object C. If the mass of object C is $p%$ of the mass of object B, what is the value of $p$?', '[]'::jsonb, 19, null),
  ('46c82a7d-aa36-500c-b332-9e6f5607ccca', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'Which of the following expressions has a factor of $x + 2b$, where $b$ is a positive integer constant?', '["$3x^{2} + 9x + 18b$", "$3x^{2} + 30x + 18b$", "$3x^{2} + 42x + 18b$", "$3x^{2} + 51x + 18b$"]'::jsonb, 20, null),
  ('6eb35c2a-99db-519b-9443-06f561cd2008', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'In triangle $XY Z$, the measure of angle $X$ is $90°$. Point $W$ lies on segment $Y Z$, and segment $WX$ is perpendicular to segment $Y Z$. The length of segment $WY$ is $588$, and the length of segment $WX$ is $441$. What is the value of $\tan Z$?', '["$\\frac{3}{5}$", "$\\frac{3}{4}$", "$\\frac{4}{5}$", "$\\frac{4}{3}$"]'::jsonb, 21, null),
  ('eadce31d-f69d-5dd1-a0d1-111daae6edde', 'a0d43bbc-8940-5bcc-9394-e29c5821f6fe', 'A parabola in the $xy$-plane has a vertex of $(1,19)$. The equation $y = -ax^{2} + bx + c$ represents this parabola, where $a$, $b$, and $c$ are positive integer constants. What is the greatest possible value of $b$?', '[]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('65344318-6149-5801-bdad-dfc5dc446af2', null, array['10']::text[], '$(4 - 2)^{2} + (c - 10)^{2} = 4$ gives $(c - 10)^{2} = 0$, so $c = 10$.'),
  ('4cbe3e08-7782-5ddf-99e0-d51965db76e1', 0, null, 'Multiply both sides by $-119x$: $w = -119vx$.'),
  ('b34247d7-c749-5e54-a56f-ba51603bfaed', null, array['48']::text[], '$3x + b - 48 = 3x$ for all $x$ only when $b = 48$.'),
  ('18ababd7-a0a2-516b-804e-4c980187e449', 2, null, 'The graph crosses the $x$-axis at $-1$ and $4$ and the $y$-axis at $-4$: $(x + 1)(x - 4) = x^{2} - 3x - 4$.'),
  ('66c19bbd-69db-5d6a-99bc-72608170da6f', 0, null, 'Slope $-\frac{7}{2}$; $5 = -\frac{7}{2}(-2) + b$ gives $b = -2$.'),
  ('1e3c5f3f-20d5-5a24-9811-bb090b39dbc6', 2, null, '$(a - 3) + 2 = 7$, so $a = 8$ and $a + 3 = 11$.'),
  ('f0c80805-5669-5771-b564-c2c4a9568255', null, array['170']::text[], 'Divide: $0.6r - 0.8s = -108$ and $0.8r + 0.6s = 106$. Solving gives $r = 20$, $s = 150$, so $r + s = 170$.'),
  ('2683886f-eada-5bc8-b75a-de807c017081', 2, null, '$(\frac{1}{8})^{x} > 0$, so $f(x) > 9(7) = 63$, and $f$ gets arbitrarily close to $63$: $k = 63$.'),
  ('7bb3620c-1259-5d4c-9a55-3800f0197d62', 2, null, 'The line meets the $x$-axis at 20: 20 boxes of cups cost \$880, so \$44 per box.'),
  ('2cedacf8-643c-5756-a44f-9fd40daee55a', 3, null, 'Setting the left sides equal gives $x = -23y$; $(10, -\frac{10}{23})$ fits and gives a positive $c$.'),
  ('4d26b06a-b642-5231-81ee-db6bfca5e8f6', 3, null, '$2x + k < y < 9 - x$ requires $2x + k < 9 - x$, so $x < \frac{9 - k}{3}$.'),
  ('12b96dda-2760-575b-9d43-6b8792998469', 2, null, '$n(44(1 - \frac{n}{100}) - 3) = 834$; $n = 30$ gives $30(30.80 - 3) = 834$.'),
  ('530b42d6-34cd-5ef4-857d-a58251e25115', 3, null, 'Increasing by 160% multiplies by $2.60$ every 24 days: $8(2.60)^{\frac{x}{24}}$.'),
  ('6015a7c7-9cf9-5ccb-b7d5-2b8b153142c7', 3, null, 'Triangles $LMR$ and $QPR$ are similar, so $RQ = \frac{10 \cdot 13}{9} = \frac{130}{9}$ and $LQ = 10 + \frac{130}{9} = \frac{220}{9}$.'),
  ('82dc9bc3-9a1e-51c8-8ab9-6e21dac624ad', 1, null, 'Data set A is modeled by about $5(2.03)^{x}$; multiplying $y$ by 30 gives about $151(2.03)^{x}$.'),
  ('cc3836fe-881e-55c6-bd9c-eea0b4490bb6', 1, null, 'Both medians are 3: the 21st of 41 values and the average of the 20th and 21st of 40 values.'),
  ('0abf8ec2-af4d-5cc8-8b4e-0263e518940c', 3, null, 'The product of the solutions is $\frac{ab}{51}$, so $k = \frac{1}{51}$.'),
  ('0e2ca8a2-bd80-5999-9468-1509a50f05d9', null, array['17']::text[], 'Base side 4. Lateral area $4 \cdot \frac{1}{2} \cdot 4 \cdot l = 8\sqrt{293}$ gives slant $l = \sqrt{293}$, so height $= \sqrt{293 - 4} = 17$.'),
  ('303ef118-abd6-520e-a27c-fc27dad6368a', null, array['60000']::text[], '$A = 4.92B$ and $A = 0.0082C$, so $C = \frac{4.92}{0.0082}B = 600B$: $p = 60,000$.'),
  ('46c82a7d-aa36-500c-b332-9e6f5607ccca', 3, null, '$x = -2b$ must be a zero: $12b^{2} - 2bk + 18b = 0$ gives $k = 6b + 9$; $k = 51$ gives the integer $b = 7$.'),
  ('6eb35c2a-99db-519b-9443-06f561cd2008', 3, null, 'The altitude makes $\tan Y = \frac{441}{588} = \frac{3}{4}$, and $Z$ is complementary to $Y$, so $\tan Z = \frac{4}{3}$.'),
  ('eadce31d-f69d-5dd1-a0d1-111daae6edde', null, array['36']::text[], 'The vertex at $x = 1$ gives $b = 2a$, and $-a + b + c = a + c = 19$. The greatest $a$ is 18 (with $c = 1$), so $b = 36$.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
